def find_user(cur, email):
    cur.execute(f"SELECT id, name FROM users WHERE email = '{email}'")
    return cur.fetchone()

def product_name(cur, item_id):
    cur.execute("SELECT name FROM products WHERE id = ?", (item_id))
    return cur.fetchone()

def products_by_ids(cur, ids):
    placeholders = ",".join("?" * len(ids))
    cur.execute(f"SELECT id, name FROM products WHERE id IN ({placeholders})", ids)
    return cur.fetchall()
